# Get all business with hours
biz = conn.execute("SELECT name, gmap_id, hours FROM business_description WHERE hours IS NOT NULL").fetchall()
import json, re

WEEKDAYS = {"Monday","Tuesday","Wednesday","Thursday","Friday"}

def parse_close_time(time_str):
    """Parse a closing time like '6PM', '6:30PM', '12AM' (midnight close treated as 24)."""
    time_str = time_str.strip()
    m = re.match(r'^(\d{1,2})(?::(\d{2}))?(AM|PM)$', time_str, re.IGNORECASE)
    if not m:
        return None
    h = int(m.group(1))
    mm = int(m.group(2)) if m.group(2) else 0
    ap = m.group(3).upper()
    if ap == 'PM' and h != 12:
        h += 12
    if ap == 'AM' and h == 12:
        h = 0  # midnight
    return h + mm/60.0

def open_after_6pm_on_weekday(hours_str):
    try:
        arr = json.loads(hours_str)
    except:
        return False
    for day, hrs in arr:
        if day not in WEEKDAYS:
            continue
        if hrs.lower() == 'closed':
            continue
        if 'open 24 hours' in hrs.lower() or hrs.lower() == 'open 24 hours':
            return True
        # parse range like "6:30AM–6PM"
        # split on en dash or hyphen
        parts = re.split(r'[–\-]', hrs)
        if len(parts) != 2:
            continue
        close = parts[1].strip()
        # Sometimes close is "12AM" meaning midnight (next day) -> open after 6pm
        ct = parse_close_time(close)
        if ct is None:
            continue
        # If close time is 0 (midnight), treat as 24
        if ct == 0:
            ct = 24
        if ct > 18:
            return True
    return False

filtered = []
for name, gid, hours in biz:
    if open_after_6pm_on_weekday(hours):
        filtered.append((name, gid, hours))

